'use client'

import { useTransition } from 'react'
import { toggleNotification } from './actions'

interface NotificationToggleProps {
  notificationsEnabled: boolean
}

export default function NotificationToggle({ notificationsEnabled }: NotificationToggleProps) {
  const [isPending, startTransition] = useTransition()

  const handleToggle = () => {
    startTransition(async () => {
      await toggleNotification()
    })
  }

  return (
    <div className="p-4 border rounded shadow-sm max-w-sm">
      <h2 className="text-lg font-semibold mb-2">Notification Settings</h2>
      <div className="flex items-center justify-between">
        <span>Enable Notifications:</span>
        <button
          onClick={handleToggle}
          disabled={isPending}
          className={`px-4 py-2 rounded text-white font-medium transition-colors ${
            notificationsEnabled ? 'bg-green-600 hover:bg-green-700' : 'bg-gray-500 hover:bg-gray-600'
          } ${isPending ? 'opacity-50 cursor-not-allowed' : ''}`}
        >
          {notificationsEnabled ? 'On' : 'Off'}
        </button>
      </div>
      {isPending && <p className="text-sm text-gray-500 mt-2">Updating preference...</p>}
    </div>
  )
}

