'use server'

import { revalidatePath } from 'next/cache'
import fs from 'fs/promises'
import path from 'path'

const dataFilePath = path.join(process.cwd(), 'data.json')

export async function getNotificationStatus() {
  try {
    const fileContent = await fs.readFile(dataFilePath, 'utf-8')
    const data = JSON.parse(fileContent)
    return data.notificationsEnabled
  } catch (error) {
    // If file doesn't exist or error, default to false and create file
    await fs.writeFile(dataFilePath, JSON.stringify({ notificationsEnabled: false }))
    return false
  }
}

export async function toggleNotification() {
  // Read current state
  const currentStatus = await getNotificationStatus()

  // Toggle state
  const newState = !currentStatus

  // Save new state
  await fs.writeFile(dataFilePath, JSON.stringify({ notificationsEnabled: newState }, null, 2))

  // Revalidate the path to refresh the UI
  revalidatePath('/')

  return newState
}

